#!/usr/bin/env python3
import sys
import os
import re
import urllib.parse
from html.parser import HTMLParser

# --- DOM Model ---

class Node:
    pass

class Document(Node):
    def __init__(self):
        self.children = []

class Element(Node):
    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag.lower()
        self.attrs = dict(attrs) if attrs else {}
        self.children = []
        self.parent = parent

class Text(Node):
    def __init__(self, data, parent=None):
        self.data = data
        self.parent = parent

class Comment(Node):
    def __init__(self, data, parent=None):
        self.data = data
        self.parent = parent

VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr"
}

HEAD_TAGS = {
    "meta", "title", "link", "base", "style", "script"
}

BLOCK_TAGS = {
    "area", "article", "aside", "address", "base", "blockquote", "body", "br",
    "dd", "details", "div", "dl", "dt", "fieldset", "figcaption", "figure",
    "footer", "form", "h1", "h2", "h3", "h4", "h5", "h6", "head", "header",
    "hr", "html", "li", "link", "main", "meta", "nav", "ol", "p", "param",
    "pre", "script", "section", "source", "style", "summary", "table", "tbody",
    "td", "tfoot", "th", "thead", "title", "tr", "track", "ul"
}

class DOMParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.doc = Document()

        self.html_elem = Element("html", parent=self.doc)
        self.doc.children.append(self.html_elem)

        self.head_elem = Element("head", parent=self.html_elem)
        self.html_elem.children.append(self.head_elem)

        self.body_elem = Element("body", parent=self.html_elem)
        self.html_elem.children.append(self.body_elem)

        self.in_head = True
        self.explicit_html = False
        self.explicit_head = False
        self.explicit_body = False

        self.stack = [self.body_elem]

    def handle_starttag(self, tag, attrs):
        tag_lower = tag.lower()
        attr_dict = {k.lower(): (v if v is not None else "") for k, v in attrs}

        if tag_lower == "html":
            self.explicit_html = True
            self.html_elem.attrs.update(attr_dict)
            self.stack = [self.html_elem]
            return
        elif tag_lower == "head":
            self.explicit_head = True
            self.head_elem.attrs.update(attr_dict)
            self.stack = [self.head_elem]
            self.in_head = True
            return
        elif tag_lower == "body":
            self.explicit_body = True
            self.body_elem.attrs.update(attr_dict)
            self.stack = [self.body_elem]
            self.in_head = False
            return

        parent = self.stack[-1] if self.stack else self.body_elem

        if self.in_head and not self.explicit_body:
            if tag_lower in HEAD_TAGS:
                parent = self.head_elem
            else:
                self.in_head = False
                parent = self.body_elem
                self.stack = [self.body_elem]

        elem = Element(tag_lower, attr_dict, parent=parent)
        parent.children.append(elem)

        if tag_lower not in VOID_TAGS:
            self.stack.append(elem)

    def handle_endtag(self, tag):
        tag_lower = tag.lower()
        if tag_lower in VOID_TAGS:
            return
        if tag_lower in ("html", "head", "body"):
            return

        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i].tag == tag_lower:
                self.stack = self.stack[:i]
                break

    def handle_data(self, data):
        if not data:
            return
        parent = self.stack[-1] if self.stack else self.body_elem
        text_node = Text(data, parent=parent)
        parent.children.append(text_node)

    def handle_comment(self, data):
        parent = self.stack[-1] if self.stack else self.body_elem
        comment_node = Comment(data, parent=parent)
        parent.children.append(comment_node)

# --- CSS Selector Matching ---

def parse_nth(expr):
    expr = expr.strip().lower()
    if expr == "odd":
        return 2, 1
    if expr == "even":
        return 2, 0
    if "n" not in expr:
        try:
            return 0, int(expr)
        except ValueError:
            return 0, 0
    parts = expr.split("n")
    a_str = parts[0].strip()
    b_str = parts[1].strip() if len(parts) > 1 else ""
    if not a_str or a_str == "+":
        a = 1
    elif a_str == "-":
        a = -1
    else:
        try:
            a = int(a_str)
        except ValueError:
            a = 0
    if not b_str:
        b = 0
    else:
        try:
            b = int(b_str)
        except ValueError:
            b = 0
    return a, b

def match_nth(index, a, b):
    if a == 0:
        return index == b
    diff = index - b
    if a > 0:
        return diff >= 0 and diff % a == 0
    else:
        return diff <= 0 and diff % a == 0

class CompoundSelector:
    def __init__(self):
        self.tag = None
        self.id = None
        self.classes = []
        self.attrs = [] # (name, op, val)
        self.pseudos = [] # (name, arg)

    def matches(self, elem):
        if not isinstance(elem, Element):
            return False
        if self.tag and self.tag != "*" and elem.tag != self.tag:
            return False
        if self.id and elem.attrs.get("id") != self.id:
            return False
        if self.classes:
            elem_classes = set(elem.attrs.get("class", "").split())
            for c in self.classes:
                if c not in elem_classes:
                    return False
        if self.attrs:
            for attr_name, op, val in self.attrs:
                if attr_name not in elem.attrs:
                    return False
                attr_val = elem.attrs[attr_name]
                if op == "=" and attr_val != val:
                    return False
                elif op == "^=" and not attr_val.startswith(val):
                    return False
                elif op == "$=" and not attr_val.endswith(val):
                    return False
                elif op == "*=" and val not in attr_val:
                    return False
                elif op == "~=" and val not in attr_val.split():
                    return False
                elif op == "|=" and attr_val != val and not attr_val.startswith(val + "-"):
                    return False
        if self.pseudos:
            for p_name, p_arg in self.pseudos:
                if not elem.parent or not isinstance(elem.parent, (Element, Document)):
                    return False
                siblings = [c for c in elem.parent.children if isinstance(c, Element)]
                if p_name == "first-child":
                    if not siblings or siblings[0] is not elem:
                        return False
                elif p_name == "last-child":
                    if not siblings or siblings[-1] is not elem:
                        return False
                elif p_name == "only-child":
                    if len(siblings) != 1 or siblings[0] is not elem:
                        return False
                elif p_name in ("nth-child", "nth-last-child"):
                    if not siblings or elem not in siblings:
                        return False
                    idx = siblings.index(elem) + 1 if p_name == "nth-child" else len(siblings) - siblings.index(elem)
                    a, b = parse_nth(p_arg)
                    if not match_nth(idx, a, b):
                        return False
                elif p_name in ("first-of-type", "last-of-type", "only-of-type", "nth-of-type", "nth-last-of-type"):
                    type_siblings = [s for s in siblings if s.tag == elem.tag]
                    if not type_siblings or elem not in type_siblings:
                        return False
                    if p_name == "first-of-type" and type_siblings[0] is not elem:
                        return False
                    if p_name == "last-of-type" and type_siblings[-1] is not elem:
                        return False
                    if p_name == "only-of-type" and (len(type_siblings) != 1 or type_siblings[0] is not elem):
                        return False
                    if p_name in ("nth-of-type", "nth-last-of-type"):
                        idx = type_siblings.index(elem) + 1 if p_name == "nth-of-type" else len(type_siblings) - type_siblings.index(elem)
                        a, b = parse_nth(p_arg)
                        if not match_nth(idx, a, b):
                            return False
                elif p_name == "empty":
                    has_children = any(isinstance(c, Element) or (isinstance(c, Text) and c.data) for c in elem.children)
                    if has_children:
                        return False
                elif p_name == "not":
                    sub_sel = parse_compound_selector(p_arg)
                    if sub_sel.matches(elem):
                        return False
        return True

def parse_compound_selector(s):
    comp = CompoundSelector()
    s = s.strip()
    pos = 0
    n = len(s)

    # Check if starts with tag or *
    m = re.match(r'^([a-zA-Z0-9_-]+|\*)', s)
    if m:
        comp.tag = m.group(1).lower()
        pos = m.end()

    while pos < n:
        ch = s[pos]
        if ch == '#':
            m = re.match(r'^#([a-zA-Z0-9_-]+)', s[pos:])
            if m:
                comp.id = m.group(1)
                pos += m.end()
            else:
                pos += 1
        elif ch == '.':
            m = re.match(r'^\.([a-zA-Z0-9_-]+)', s[pos:])
            if m:
                comp.classes.append(m.group(1))
                pos += m.end()
            else:
                pos += 1
        elif ch == '[':
            end = s.find(']', pos)
            if end != -1:
                attr_str = s[pos+1:end].strip()
                pos = end + 1
                m_op = re.search(r'([\^\|\*\~\$]?=)', attr_str)
                if m_op:
                    op = m_op.group(1)
                    aname = attr_str[:m_op.start()].strip().lower()
                    aval = attr_str[m_op.end():].strip().strip('"\'')
                    comp.attrs.append((aname, op, aval))
                else:
                    comp.attrs.append((attr_str.lower(), "exists", None))
            else:
                pos += 1
        elif ch == ':':
            m = re.match(r'^:([a-zA-Z0-9_-]+)(\((.*?)\))?', s[pos:])
            if m:
                pname = m.group(1).lower()
                parg = m.group(3) if m.group(3) is not None else ""
                comp.pseudos.append((pname, parg))
                pos += m.end()
            else:
                pos += 1
        else:
            pos += 1
    return comp

def parse_selector(sel_str):
    # Splits comma-separated groups
    groups = []
    # Simple comma split aware of [] and ()
    in_sq = False
    in_paren = False
    cur = ""
    for ch in sel_str:
        if ch == '[': in_sq = True
        elif ch == ']': in_sq = False
        elif ch == '(': in_paren = True
        elif ch == ')': in_paren = False

        if ch == ',' and not in_sq and not in_paren:
            groups.append(cur.strip())
            cur = ""
        else:
            cur += ch
    if cur.strip():
        groups.append(cur.strip())

    parsed_groups = []
    for group in groups:
        # Tokenize by combinators: >, +, ~, space
        tokens = []
        i = 0
        gn = len(group)
        buf = ""
        comb = None
        while i < gn:
            c = group[i]
            if c in ('>', '+', '~') and not in_sq and not in_paren:
                if buf.strip():
                    tokens.append((parse_compound_selector(buf), comb))
                    buf = ""
                comb = c
            elif c == ' ' and not in_sq and not in_paren:
                # check if whitespace is combinator
                j = i
                while j < gn and group[j] == ' ':
                    j += 1
                if j < gn and group[j] in ('>', '+', '~'):
                    i = j - 1 # skip spaces before combinator
                else:
                    if buf.strip():
                        tokens.append((parse_compound_selector(buf), comb))
                        buf = ""
                    comb = ' '
            else:
                buf += c
            i += 1
        if buf.strip():
            tokens.append((parse_compound_selector(buf), comb))
        parsed_groups.append(tokens)
    return parsed_groups

def match_sequence(tokens, idx, elem):
    if idx < 0:
        return True
    comp, comb = tokens[idx]
    if not comp.matches(elem):
        return False
    if idx == 0:
        return True

    prev_comb = tokens[idx][1] # combinator leading to this compound
    if prev_comb == '>':
        parent = elem.parent
        if parent and isinstance(parent, Element):
            return match_sequence(tokens, idx - 1, parent)
        return False
    elif prev_comb == ' ':
        curr = elem.parent
        while curr and isinstance(curr, Element):
            if match_sequence(tokens, idx - 1, curr):
                return True
            curr = curr.parent
        return False
    elif prev_comb == '+':
        if not elem.parent: return False
        sibs = [c for c in elem.parent.children if isinstance(c, Element)]
        e_idx = sibs.index(elem) if elem in sibs else -1
        if e_idx > 0:
            return match_sequence(tokens, idx - 1, sibs[e_idx - 1])
        return False
    elif prev_comb == '~':
        if not elem.parent: return False
        sibs = [c for c in elem.parent.children if isinstance(c, Element)]
        e_idx = sibs.index(elem) if elem in sibs else -1
        for s in range(e_idx - 1, -1, -1):
            if match_sequence(tokens, idx - 1, sibs[s]):
                return True
        return False
    return False

def select_nodes(root, selector_str):
    parsed_groups = parse_selector(selector_str)
    all_elements = []

    def collect_elements(node):
        if isinstance(node, Element):
            all_elements.append(node)
        if hasattr(node, "children"):
            for c in node.children:
                collect_elements(c)

    collect_elements(root)

    matched = []
    for elem in all_elements:
        for tokens in parsed_groups:
            if match_sequence(tokens, len(tokens) - 1, elem):
                if elem not in matched:
                    matched.append(elem)
                break
    return matched

# --- Serialization ---

def escape_text(text):
    return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

def escape_attr(val):
    return val.replace("&", "&amp;").replace('"', "&quot;")

def serialize_node(node):
    if isinstance(node, Text):
        return escape_text(node.data)
    elif isinstance(node, Comment):
        return f"<!--{node.data}-->"
    elif isinstance(node, Element):
        attrs_str = ""
        if node.attrs:
            sorted_keys = sorted(node.attrs.keys())
            attrs_str = "".join([f' {k}="{escape_attr(node.attrs[k])}"' for k in sorted_keys])
        if node.tag in VOID_TAGS:
            return f"<{node.tag}{attrs_str}>"
        else:
            children_str = "".join([serialize_node(c) for c in node.children])
            return f"<{node.tag}{attrs_str}>{children_str}</{node.tag}>"
    elif isinstance(node, Document):
        return "".join([serialize_node(c) for c in node.children])
    return ""

def pretty_serialize_node(node, depth=0, is_root=True):
    if isinstance(node, Text):
        return escape_text(node.data)
    elif isinstance(node, Comment):
        return f"<!--{node.data}-->"
    elif isinstance(node, Element):
        indent = "  " * depth
        attrs_str = ""
        if node.attrs:
            sorted_keys = sorted(node.attrs.keys())
            attrs_str = "".join([f' {k}="{escape_attr(node.attrs[k])}"' for k in sorted_keys])

        prefix = "\n" if not is_root else ""

        if node.tag in VOID_TAGS:
            return f"{prefix}{indent}<{node.tag}{attrs_str}>"
        else:
            children_parts = []
            for c in node.children:
                if isinstance(c, Element) and c.tag in BLOCK_TAGS:
                    children_parts.append(pretty_serialize_node(c, depth + 1, is_root=False))
                else:
                    children_parts.append(pretty_serialize_node(c, depth + 1, is_root=True))
            children_str = "".join(children_parts)

            has_block_child = any(isinstance(c, Element) and c.tag in BLOCK_TAGS for c in node.children)
            closing_indent = f"\n{indent}" if has_block_child else ""

            return f"{prefix}{indent}<{node.tag}{attrs_str}>{children_str}{closing_indent}</{node.tag}>"
    return ""

# --- Main CLI ---

def print_help(bin_name):
    print(f"""htmlq 0.4.0
Michael Maclean <michael@mgdm.net>
Runs CSS selectors on HTML

USAGE:
    {bin_name} [FLAGS] [OPTIONS] [--] [selector]...

FLAGS:
    -B, --detect-base          Try to detect the base URL from the <base> tag in the document. If not found, default to
                               the value of --base, if supplied
    -h, --help                 Prints help information
    -w, --ignore-whitespace    When printing text nodes, ignore those that consist entirely of whitespace
    -p, --pretty               Pretty-print the serialised output
    -t, --text                 Output only the contents of text nodes inside selected elements
    -V, --version              Prints version information

OPTIONS:
    -a, --attribute <attribute>         Only return this attribute (if present) from selected elements
    -b, --base <base>                   Use this URL as the base for links
    -f, --filename <FILE>               The input file. Defaults to stdin
    -o, --output <FILE>                 The output file. Defaults to stdout
    -r, --remove-nodes <SELECTOR>...    Remove nodes matching this expression before output. May be specified multiple
                                        times

ARGS:
    <selector>...    The CSS expression to select [default: html]""")

def print_error(bin_name, msg):
    sys.stderr.write(f"error: {msg}\n\nUSAGE:\n    {bin_name} [FLAGS] [OPTIONS] [--] [selector]...\n\nFor more information try --help\n")

def parse_args(argv):
    bin_name = os.path.basename(argv[0]) if argv else "executable"
    args = argv[1:]

    detect_base = False
    ignore_whitespace = False
    pretty = False
    text = False
    attribute = None
    base = None
    filename = None
    output = None
    remove_nodes = []
    selectors = []

    i = 0
    n = len(args)
    parsing_options = True

    while i < n:
        arg = args[i]
        if parsing_options and arg == "--":
            parsing_options = False
            i += 1
            continue

        if parsing_options and arg.startswith("-") and arg != "-":
            if arg in ("-h", "--help"):
                print_help(bin_name)
                sys.exit(0)
            elif arg in ("-V", "--version"):
                print("htmlq 0.4.0")
                sys.exit(0)
            elif arg in ("-B", "--detect-base"):
                detect_base = True
            elif arg in ("-w", "--ignore-whitespace"):
                ignore_whitespace = True
            elif arg in ("-p", "--pretty"):
                pretty = True
            elif arg in ("-t", "--text"):
                text = True
            elif arg in ("-a", "--attribute"):
                if i + 1 >= n:
                    print_error(bin_name, "The argument '--attribute <attribute>' requires a value but none was supplied")
                    sys.exit(1)
                attribute = args[i+1]
                i += 1
            elif arg.startswith("-a="):
                attribute = arg.split("=", 1)[1]
            elif arg.startswith("--attribute="):
                attribute = arg.split("=", 1)[1]
            elif arg in ("-b", "--base"):
                if i + 1 >= n:
                    print_error(bin_name, "The argument '--base <base>' requires a value but none was supplied")
                    sys.exit(1)
                base = args[i+1]
                i += 1
            elif arg.startswith("-b="):
                base = arg.split("=", 1)[1]
            elif arg.startswith("--base="):
                base = arg.split("=", 1)[1]
            elif arg in ("-f", "--filename"):
                if i + 1 >= n:
                    print_error(bin_name, "The argument '--filename <FILE>' requires a value but none was supplied")
                    sys.exit(1)
                filename = args[i+1]
                i += 1
            elif arg.startswith("-f="):
                filename = arg.split("=", 1)[1]
            elif arg.startswith("--filename="):
                filename = arg.split("=", 1)[1]
            elif arg in ("-o", "--output"):
                if i + 1 >= n:
                    print_error(bin_name, "The argument '--output <FILE>' requires a value but none was supplied")
                    sys.exit(1)
                output = args[i+1]
                i += 1
            elif arg.startswith("-o="):
                output = arg.split("=", 1)[1]
            elif arg.startswith("--output="):
                output = arg.split("=", 1)[1]
            elif arg in ("-r", "--remove-nodes"):
                i += 1
                while i < n:
                    if args[i] == "--":
                        break
                    if args[i].startswith("-") and args[i] != "-":
                        i -= 1
                        break
                    remove_nodes.append(args[i])
                    i += 1
            elif arg.startswith("-r="):
                remove_nodes.append(arg.split("=", 1)[1])
            elif arg.startswith("--remove-nodes="):
                remove_nodes.append(arg.split("=", 1)[1])
            else:
                if arg.startswith("-") and not arg.startswith("--"):
                    valid = True
                    for char in arg[1:]:
                        if char == 'B': detect_base = True
                        elif char == 'w': ignore_whitespace = True
                        elif char == 'p': pretty = True
                        elif char == 't': text = True
                        elif char == 'h': print_help(bin_name); sys.exit(0)
                        elif char == 'V': print("htmlq 0.4.0"); sys.exit(0)
                        else: valid = False; break
                    if not valid:
                        print_error(bin_name, f"Found argument '{arg}' which wasn't expected, or isn't valid in this context")
                        sys.exit(1)
                else:
                    print_error(bin_name, f"Found argument '{arg}' which wasn't expected, or isn't valid in this context")
                    sys.exit(1)
        else:
            selectors.append(arg)
        i += 1

    if not selectors:
        selectors = ["html"]

    return {
        "detect_base": detect_base,
        "ignore_whitespace": ignore_whitespace,
        "pretty": pretty,
        "text": text,
        "attribute": attribute,
        "base": base,
        "filename": filename,
        "output": output,
        "remove_nodes": remove_nodes,
        "selectors": selectors
    }

def main():
    cfg = parse_args(sys.argv)

    # Read input
    if cfg["filename"] and cfg["filename"] != "-":
        try:
            with open(cfg["filename"], "r", encoding="utf-8", errors="replace") as f:
                html_content = f.read()
        except Exception as e:
            sys.stderr.write(f"\nthread 'main' panicked at src/main.rs:196:37:\nshould have opened input file: Os {{ code: 2, kind: NotFound, message: \"{e}\" }}\n")
            sys.exit(101)
    else:
        html_content = sys.stdin.read()

    parser = DOMParser()
    parser.feed(html_content)
    doc = parser.doc

    # Handle base URL
    base_url = None
    if cfg["detect_base"]:
        bases = select_nodes(doc, "base")
        if bases and "href" in bases[0].attrs:
            base_url = bases[0].attrs["href"]
    if not base_url and cfg["base"]:
        base_url = cfg["base"]

    # Handle remove-nodes
    if cfg["remove_nodes"]:
        for r_sel in cfg["remove_nodes"]:
            to_remove = select_nodes(doc, r_sel)
            for r_node in to_remove:
                if r_node.parent and r_node in r_node.parent.children:
                    r_node.parent.children.remove(r_node)
                    r_node.parent = None

    # Execute positional chaining selectors
    current_nodes = [doc]
    for sel in cfg["selectors"]:
        next_nodes = []
        for n in current_nodes:
            matches = select_nodes(n, sel)
            for m in matches:
                if m not in next_nodes:
                    next_nodes.append(m)
        current_nodes = next_nodes

    # Prepare output stream
    out_file = sys.stdout
    if cfg["output"] and cfg["output"] != "-":
        try:
            out_file = open(cfg["output"], "w", encoding="utf-8")
        except Exception as e:
            sys.stderr.write(f"\nthread 'main' panicked at src/main.rs:210:37:\nfailed to create output file: {e}\n")
            sys.exit(101)

    try:
        if cfg["attribute"]:
            attr_name = cfg["attribute"].lower()
            for node in current_nodes:
                if isinstance(node, Element) and attr_name in node.attrs:
                    val = node.attrs[attr_name]
                    if base_url and attr_name == "href" and node.tag in ("a", "link", "area"):
                        try:
                            val = urllib.parse.urljoin(base_url, val)
                        except Exception:
                            pass
                    out_file.write(val + "\n")
        elif cfg["text"]:
            for node in current_nodes:
                text_nodes = []
                def collect_text(n):
                    if isinstance(n, Text):
                        text_nodes.append(n.data)
                    if hasattr(n, "children"):
                        for c in n.children:
                            collect_text(c)
                collect_text(node)

                if cfg["ignore_whitespace"]:
                    for t in text_nodes:
                        if t.strip():
                            out_file.write(t + "\n")
                    out_file.write("\n")
                else:
                    combined = "".join(text_nodes)
                    out_file.write(combined + "\n")
        else:
            for node in current_nodes:
                if cfg["pretty"]:
                    s = pretty_serialize_node(node)
                    out_file.write(s + "\n")
                else:
                    s = serialize_node(node)
                    out_file.write(s + "\n")
    finally:
        if out_file is not sys.stdout:
            out_file.close()

if __name__ == "__main__":
    main()
