    return False

def select_nodes(root, selector_str):
    parsed_groups = parse_selector(selector_str)
    all_elements = []

    def collect_elements(node):
        if isinstance(node, Element):
            all_elements.append(node)
        if hasattr(node, "children"):
            for c in node.children:
                collect_elements(c)

    collect_elements(root)

    matched = []
    for elem in all_elements:
        for tokens in parsed_groups:
            if match_sequence(tokens, len(tokens) - 1, elem):
