                comp.classes.append(m.group(1))
                pos += m.end()
            else:
                pos += 1
        elif ch == '[':
            end = s.find(']', pos)
            if end != -1:
                attr_str = s[pos+1:end].strip()
                pos = end + 1
                m_op = re.search(r'([\^\|\*\~\$]?=)', attr_str)
                if m_op:
                    op = m_op.group(1)
                    aname = attr_str[:m_op.start()].strip().lower()
                    aval = attr_str[m_op.end():].strip().strip('"\'')
                    comp.attrs.append((aname, op, aval))
                else:
                    comp.attrs.append((attr_str.lower(), "exists", None))
