# --- CSS Selector Matching ---

def parse_nth(expr):
    expr = expr.strip().lower()
    if expr == "odd":
        return 2, 1
    if expr == "even":
        return 2, 0
    if "n" not in expr:
        try:
            return 0, int(expr)
        except ValueError:
            return 0, 0
    parts = expr.split("n")
    a_str = parts[0].strip()
    b_str = parts[1].strip() if len(parts) > 1 else ""
    if not a_str or a_str == "+":
        a = 1
    elif a_str == "-":
        a = -1
    else:
        try:
            a = int(a_str)
        except ValueError:
            a = 0
    if not b_str:
        b = 0
    else:
        try:
            b = int(b_str)
        except ValueError:
            b = 0
    return a, b

def match_nth(index, a, b):
    if a == 0:
        return index == b
    diff = index - b
    if a > 0:
        return diff >= 0 and diff % a == 0
    else:
        return diff <= 0 and diff % a == 0

