        "pretty": pretty,
        "text": text,
        "attribute": attribute,
        "base": base,
        "filename": filename,
        "output": output,
        "remove_nodes": remove_nodes,
        "selectors": selectors
    }

def main():
    cfg = parse_args(sys.argv)

