#!/usr/bin/env python3
import sys
import os
import re
import urllib.parse
from html.parser import HTMLParser

# --- DOM Model ---

class Node:
    pass

class Document(Node):
    def __init__(self):
        self.children = []

class Element(Node):
    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag.lower()
        self.attrs = dict(attrs) if attrs else {}
        self.children = []
        self.parent = parent

class Text(Node):
    def __init__(self, data, parent=None):
        self.data = data
        self.parent = parent

class Comment(Node):
    def __init__(self, data, parent=None):
        self.data = data
        self.parent = parent

VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr"
}

HEAD_TAGS = {
    "meta", "title", "link", "base", "style", "script"
}

BLOCK_TAGS = {
    "area", "article", "aside", "address", "base", "blockquote", "body", "br",
    "dd", "details", "div", "dl", "dt", "fieldset", "figcaption", "figure",
    "footer", "form", "h1", "h2", "h3", "h4", "h5", "h6", "head", "header",
    "hr", "html", "li", "link", "main", "meta", "nav", "ol", "p", "param",
    "pre", "script", "section", "source", "style", "summary", "table", "tbody",
    "td", "tfoot", "th", "thead", "title", "tr", "track", "ul"
}

class DOMParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.doc = Document()

        self.html_elem = Element("html", parent=self.doc)
        self.doc.children.append(self.html_elem)

        self.head_elem = Element("head", parent=self.html_elem)
        self.html_elem.children.append(self.head_elem)

        self.body_elem = Element("body", parent=self.html_elem)
        self.html_elem.children.append(self.body_elem)

        self.in_head = True
        self.explicit_html = False
        self.explicit_head = False
        self.explicit_body = False

        self.stack = [self.body_elem]

    def handle_starttag(self, tag, attrs):
        tag_lower = tag.lower()
        attr_dict = {k.lower(): (v if v is not None else "") for k, v in attrs}

        if tag_lower == "html":
            self.explicit_html = True
            self.html_elem.attrs.update(attr_dict)
            self.stack = [self.html_elem]
            return
        elif tag_lower == "head":
            self.explicit_head = True
            self.head_elem.attrs.update(attr_dict)
            self.stack = [self.head_elem]
            self.in_head = True
            return
        elif tag_lower == "body":
            self.explicit_body = True
            self.body_elem.attrs.update(attr_dict)
            self.stack = [self.body_elem]
            self.in_head = False
            return

        parent = self.stack[-1] if self.stack else self.body_elem

        if self.in_head and not self.explicit_body:
            if tag_lower in HEAD_TAGS:
                parent = self.head_elem
            else:
                self.in_head = False
                parent = self.body_elem
                self.stack = [self.body_elem]

        elem = Element(tag_lower, attr_dict, parent=parent)
        parent.children.append(elem)

        if tag_lower not in VOID_TAGS:
            self.stack.append(elem)

    def handle_endtag(self, tag):
        tag_lower = tag.lower()
        if tag_lower in VOID_TAGS:
            return
        if tag_lower in ("html", "head", "body"):
            return

        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i].tag == tag_lower:
                self.stack = self.stack[:i]
                break

    def handle_data(self, data):
        if not data:
            return
        parent = self.stack[-1] if self.stack else self.body_elem
        text_node = Text(data, parent=parent)
        parent.children.append(text_node)

    def handle_comment(self, data):
        parent = self.stack[-1] if self.stack else self.body_elem
        comment_node = Comment(data, parent=parent)
        parent.children.append(comment_node)

# --- CSS Selector Matching ---

def parse_nth(expr):
    expr = expr.strip().lower()
    if expr == "odd":
        return 2, 1
    if expr == "even":
        return 2, 0
    if "n" not in expr:
        try:
            return 0, int(expr)
        except ValueError:
            return 0, 0
    parts = expr.split("n")
    a_str = parts[0].strip()
    b_str = parts[1].strip() if len(parts) > 1 else ""
    if not a_str or a_str == "+":
        a = 1
    elif a_str == "-":
        a = -1
    else:
        try:
            a = int(a_str)
        except ValueError:
            a = 0
    if not b_str:
        b = 0
    else:
        try:
            b = int(b_str)
        except ValueError:
            b = 0
    return a, b

def match_nth(index, a, b):
    if a == 0:
        return index == b
    diff = index - b
    if a > 0:
        return diff >= 0 and diff % a == 0
    else:
        return diff <= 0 and diff % a == 0

class CompoundSelector:
    def __init__(self):
        self.tag = None
        self.id = None
        self.classes = []
        self.attrs = [] # (name, op, val)
        self.pseudos = [] # (name, arg)

    def matches(self, elem):
        if not isinstance(elem, Element):
            return False
        if self.tag and self.tag != "*" and elem.tag != self.tag:
            return False
        if self.id and elem.attrs.get("id") != self.id:
            return False
        if self.classes:
            elem_classes = set(elem.attrs.get("class", "").split())
            for c in self.classes:
                if c not in elem_classes:
                    return False
        if self.attrs:
            for attr_name, op, val in self.attrs:
                if attr_name not in elem.attrs:
                    return False
                attr_val = elem.attrs[attr_name]
                if op == "=" and attr_val != val:
                    return False
                elif op == "^=" and not attr_val.startswith(val):
                    return False
                elif op == "$=" and not attr_val.endswith(val):
                    return False
                elif op == "*=" and val not in attr_val:
                    return False
                elif op == "~=" and val not in attr_val.split():
                    return False
                elif op == "|=" and attr_val != val and not attr_val.startswith(val + "-"):
                    return False
        if self.pseudos:
            for p_name, p_arg in self.pseudos:
                if not elem.parent or not isinstance(elem.parent, (Element, Document)):
                    return False
                siblings = [c for c in elem.parent.children if isinstance(c, Element)]
                if p_name == "first-child":
                    if not siblings or siblings[0] is not elem:
                        return False
                elif p_name == "last-child":
                    if not siblings or siblings[-1] is not elem:
                        return False
                elif p_name == "only-child":
                    if len(siblings) != 1 or siblings[0] is not elem:
                        return False
                elif p_name in ("nth-child", "nth-last-child"):
                    if not siblings or elem not in siblings:
                        return False
                    idx = siblings.index(elem) + 1 if p_name == "nth-child" else len(siblings) - siblings.index(elem)
                    a, b = parse_nth(p_arg)
